// fayl: app/page.tsx
import ClientRecipes from "./ClientRecipes"

type Recipe = { id: number; title: string }

// Next.js usuli: ma'lumot serverda olinadi, HTML tayyor holda keladi
export default async function Home() {
  const recipes: Recipe[] = await (await fetch(`${process.env.API_URL}/recipes?page=1&limit=2`)).json()
  return (
    <main>
      <section>
        <h2>Serverda (Next.js)</h2>
        <ul>{recipes.map((r) => <li key={r.id}>{r.title}</li>)}</ul>
      </section>
      <ClientRecipes />
    </main>
  )
}

// fayl: app/ClientRecipes.tsx
"use client"
import { useEffect, useState } from "react"

// Oddiy React (SPA) usuli: sahifa bo'sh keladi, ma'lumot brauzerda olinadi
export default function ClientRecipes() {
  const [recipes, setRecipes] = useState<{ id: number; title: string }[] | null>(null)
  useEffect(() => {
    fetch("/api/recipes").then((r) => r.json()).then(setRecipes)
  }, [])
  return (
    <section>
      <h2>Brauzerda (SPA)</h2>
      {recipes ? <ul>{recipes.map((r) => <li key={r.id}>{r.title}</li>)}</ul> : <p>Yuklanmoqda...</p>}
    </section>
  )
}

