    "app/page.tsx",
    "app/(marketing)/about/page.tsx",
    "app/blog/[slug]/page.tsx",
    "app/blog/_components/PostCard.tsx",
    "app/blog/layout.tsx",
    "app/api/menu/route.ts",
    "app/dashboard/@team/page.tsx",
]

function toUrl(file) {
    const parts = file.replace(/^app\//, "").split("/")
    const name = parts.pop()
    if (!/^(page|route)\./.test(name)) return "URL yo'q (maxsus fayl emas)"
    if (parts.some((p) => p.startsWith("_"))) return "URL yo'q (private papka)"
    const segments = parts.filter((p) => !p.startsWith("(") && !p.startsWith("@"))
    const url = "/" + segments.join("/")
    return parts.some((p) => p.startsWith("@")) ? `${url} (slot ichida)` : url
}

for (const file of files) console.log(file.padEnd(36), "→", toUrl(file))

